function remember(button) {
    var usernameField = button.form.querySelector("input[username-field]");
    var username = usernameField ? usernameField.value : "";

    if (username !== "") {
        saveValueToCookie(username);
        setLoginCardCookie(username);
    }
}

function setLoginCardCookie(username) {
    var date = new Date();
    date.setTime(date.getTime() + 1296e6);
    var expires = date.toGMTString();

    try { document.cookie = 'username=' + encodeURIComponent(username) + ';expires=' + expires + ';path=/;SameSite=Lax' + (location.protocol === 'https:' ? ';Secure' : ''); } catch (ignore) {}
}

function getLoginCardCookie() {
    var data = { username: "" };

    var cookies = [];
    try { cookies = document.cookie.split(';'); } catch (ignore) { return data; }
    cookies.forEach(function (cookie) {
        cookie = cookie.trim().split('=');
        if (cookie[0] === 'username') {
            try { data.username = decodeURIComponent(cookie[1] || ''); } catch (ignore) { data.username = ''; }
        }
    });

    return data;
}

function cookieLogin() {
    if (document.querySelector("[enable-hot-cookie]") === null) {
        return;
    }

    var card = getLoginCardCookie();

    if (card.username !== "" && !loginPending) {
        var route = typeof getConfirmedCardSpeed === 'function' ? getConfirmedCardSpeed(card.username) : null;
        if (!route) {
            /* Old 15-day cookie has no trustworthy associated domain: prompt instead of guessing. */
            if (document.login && document.login.username) document.login.username.value = card.username;
            if (typeof showErrorNotice === 'function')
                showErrorNotice('اختر نوع الكرت أو السرعة ثم اضغط تسجيل الدخول.');
            return;
        }
        currentLoginUsername = card.username;
        pendingRememberUsername = card.username;
        pendingRememberSpeed = route;
        if (typeof applySpeedChoice === 'function') applySpeedChoice(route);
        showLoginBusy(true);
        ++requestEpoch;
        /* Automatic prior-card login remains supported for existing users. */
        var speed = route;
        var fields = {username:card.username};
        if (speed !== 'hotspot') fields.domain = speed;
        if (typeof signalChosenSpeed === 'function') signalChosenSpeed(speed, function(){
            getRequest('/login?var=callBack', fields, 'login');
        });
        else getRequest('/login?var=callBack', fields, 'login');
    }
}

function clearCookies() {
    try { document.cookie = "username=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/;SameSite=Lax"; } catch (ignore) {}
}

function clearStoredCards() {
    /* This explicit action does not log the current user out of MikroTik. */
    try { document.cookie='storedValues=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/;SameSite=Lax'; } catch (ignore) {}
    clearCookies();
    try { localStorage.removeItem('alameer_verified_card_routes_v1'); } catch (ignore) {}
    if (typeof renderPreviousCards === 'function') renderPreviousCards();
}
function registerClearCookieButton() {
    var button = document.querySelector("[clear-hot-cookie]");

    if (button !== null) {
        button.addEventListener("click", function () {
            clearCookies();
        });
    }

}

function getStoredValuesFromCookie() {
    var stored = "";
    var cookies = [];
    try { cookies = document.cookie ? document.cookie.split(";") : []; } catch (ignore) { return []; }

    for (var i = 0; i < cookies.length; i++) {
        var cookie = cookies[i].trim();

        if (cookie.indexOf("storedValues=") === 0) {
            stored = cookie.substring("storedValues=".length);
            break;
        }
    }

    if (stored === "") {
        return [];
    }

    var cards;
    try { cards = JSON.parse(decodeURIComponent(stored)); }
    catch (e) {
        try { cards = JSON.parse(stored); }
        catch (ignore) { return []; }
    }
    if (!Array.isArray(cards)) return [];
    var safe = [];
    for (var i = 0; i < cards.length && i < 20; i++) {
        if (typeof cards[i] === 'string' && cards[i].length <= 128) safe.push(cards[i]);
    }
    return safe.slice(-2);
}

function saveValueToCookie(value) {
    var values = getStoredValuesFromCookie();
    var index = values.indexOf(value);

    if (index !== -1) {
        values.splice(index, 1);
    }

    values.push(value);
    values = values.slice(-2);

    var date = new Date();
    date.setTime(date.getTime() + 2592e6);

    try { document.cookie = 'storedValues=' + encodeURIComponent(JSON.stringify(values)) + ';expires=' + date.toUTCString() + ';path=/;SameSite=Lax' + (location.protocol === 'https:' ? ';Secure' : ''); } catch (ignore) {}
    renderPreviousCards();
}

function renderPreviousCards() {
    var list = document.getElementById("previousCardsList");
    var empty = document.getElementById("previousCardsEmpty");

    if (list === null || empty === null) {
        return;
    }

    var values = getStoredValuesFromCookie().slice(-2).reverse();

    list.innerHTML = "";
    if (values.length === 0) empty.classList.add('show');
    else empty.classList.remove('show');

    values.forEach(function (card) {
        var item = document.createElement("button");
        item.type = "button";
        item.className = "previous-card-item";
        item.textContent = card;

        item.addEventListener("click", function () {
            var usernameField = document.login.querySelector("input[username-field]");

            if (usernameField !== null) {
                usernameField.value = card;
                var savedRoute=typeof getConfirmedCardSpeed==='function' ? getConfirmedCardSpeed(card) : null;
                if(savedRoute && typeof applySpeedChoice==='function') applySpeedChoice(savedRoute);
                try {
                    var ev;
                    if (typeof Event === 'function') ev = new Event('input', {bubbles:true});
                    else { ev = document.createEvent('Event'); ev.initEvent('input', true, false); }
                    usernameField.dispatchEvent(ev);
                } catch (ignore) {}
            }

            closePreviousCardsPopup();
        });

        list.appendChild(item);
    });
}

function closePreviousCardsPopup() {
    var popup = document.getElementById("previous-cards");

    if (popup !== null) {
        popup.classList.remove("active");
        popup.style.display = "none";
    }

    if (typeof showLoginPage === "function") {
        showLoginPage();
    } else {
        var login = document.getElementById("login");
        if (login !== null) {
            login.style.display = "block";
            login.classList.remove("inactive");
        }
    }
}

document.addEventListener("DOMContentLoaded", function () {
    registerClearCookieButton();
    var clearSaved=document.getElementById('clearSavedCardsBtn');
    if(clearSaved) clearSaved.addEventListener('click',function(){
        if(window.confirm('هل تريد مسح جميع الكروت المحفوظة من هذا الهاتف؟')) clearStoredCards();
    });
    renderPreviousCards();
}, false);
